      "card_ids": ["C18", "C67", "C19", "C03"],
      "claim": "Sulpiride and levosulpiride, despite incomplete absorption, show oral bioavailability of 23-35% in humans, supporting F >= 20%."
    },
    {
      "card_ids": ["C08", "C48", "C63"],
      "claim": "Encainide, a dimethoxyphenyl-containing drug, has oral bioavailability of 20-42% in healthy subjects, supporting high bioavailability."
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a dimethoxy-substituted fused bicyclic amine, has an absolute oral bioavailability of approximately 49%, supporting high bioavailability."
    },
    {
      "card_ids": ["C37"],
      "claim": "Colchicine, a polymethoxylated fused-ring drug, has a mean absolute oral bioavailability of 55%, supporting high bioavailability."
    },
    {
      "card_ids": ["C73", "C41", "C55"],
      "claim": "Alfentanil baseline oral bioavailability in healthy volunteers is 37-51%; low values occur only with rifampin coadministration, so normal-condition evidence supports high bioavailability."
    }
  ],
